  el('forge-copy').onclick=()=>{void(async()=>{try{const {prompt}=prepareProject();el('forge-output').open=true;if(window.navigator?.clipboard?.writeText){await window.navigator.clipboard.writeText(prompt);el('forge-project-status').textContent='Project prompt copied. Paste it into Codex to create and build the firmware.';}else{el('forge-prompt').focus?.();el('forge-prompt').select?.();el('forge-project-status').textContent='Select and copy the project prompt below, then paste it into Codex.';}}catch(error){el('forge-project-status').textContent=error.message;}})();};
  el('forge-download').onclick=()=>{try{const {config}=prepareProject();const blob=new Blob([JSON.stringify(config,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=config.project.slug+'.fm1-forge.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);el('forge-project-status').textContent='Configuration downloaded. This does not build or transfer firmware.';}catch(error){el('forge-output').open=true;el('forge-project-status').textContent=(error.message||'Download unavailable.')+' Copy the configuration below.';}};
